    fn sign_community_request<T: Serialize>(
        path: &str,
        payload: T,
        keypair: &arc_crypto::KeyPair,
    ) -> Result<CommunitySignedRequest<T>, String> {
        super::sign_community_request(path, payload, keypair, Hash256::ZERO, None)
    }

