    #[test]
    fn community_rpc_origins_require_https_remotely_and_canonicalize() {
        let bases = validate_community_rpc_bases(
            &[
                "https://Seed.Example:443/".to_string(),
                "http://127.0.0.1:9090".to_string(),
                "https://seed.example".to_string(),
            ],
            false,
        )
        .expect("HTTPS remote and loopback HTTP origins are valid");
        assert_eq!(bases.len(), 2, "canonical duplicates are removed");
        assert!(bases.iter().any(|base| base == "https://seed.example"));
        assert!(bases.iter().any(|base| base == "http://127.0.0.1:9090"));

        let error = validate_community_rpc_bases(&["http://10.0.0.8:9090".to_string()], false)
            .expect_err("remote plaintext must fail closed");
        assert!(error.contains("must use https"), "{error}");
        assert!(
            validate_community_rpc_bases(&["http://10.0.0.8:9090".to_string()], true).is_ok(),
            "the explicit disposable-dev override is the only remote HTTP escape hatch"
        );
    }

    #[test]
    fn community_rpc_origins_reject_dangerous_url_forms() {
        for dangerous in [
            "ftp://seed.example",
            "https://user@seed.example",
            "https://seed.example/private-prefix",
            "https://seed.example?target=other",
            "https://seed.example#fragment",
            "http://0.0.0.0:9090",
            "https://seed.example:0",
        ] {
            assert!(
                validate_community_rpc_bases(&[dangerous.to_string()], false).is_err(),
                "dangerous origin unexpectedly accepted: {dangerous}"
            );
        }
    }

    #[tokio::test]
    async fn public_reward_endpoints_fail_closed_when_runtime_prerequisites_are_unavailable() {
        let mut node = fake_node_with_workers(Vec::new());
        node.community_rewards_v1_enabled = true;
        node.state
            .set_community_rewards_v1_activation_height(Some(0));
        assert!(community_rewards_v1_protocol_active(&node));
        assert!(!community_rewards_v1_effective(&node));

        let Json(economics) = economics_rewards(AxumState(node.clone())).await;
        let Json(community) = community_list(AxumState(node.clone())).await;
        let Json(policy) = community_reward_policy(AxumState(node.clone())).await;
        let Json(approval) = community_reward_approval_status(
            AxumState(node.clone()),
            axum::extract::Path(format!("0x{}", Hash256::ZERO.to_hex())),
        )
        .await
        .expect("well-formed job ids always have an approval status");
        let Json(earnings) = worker_earnings(
            AxumState(node),
            axum::extract::Path(format!("0x{}", Hash256::ZERO.to_hex())),
        )
        .await
        .expect("zero address is a valid query");

        for response in [&economics, &community, &earnings] {
            assert_eq!(response["community_rewards_v1_protocol_active"], true);
            assert_eq!(
                response["community_rewards_v1_approval_collection_ready"],
                true
            );
            assert_eq!(response["community_rewards_v1_enabled"], false);
            assert!(
                response["community_rewards_v1_note"]
                    .as_str()
                    .unwrap()
                    .contains("issuance remains fail-closed until")
            );
        }
        assert_eq!(policy["schema"], "arc.community.reward-policy.v1");
        assert_eq!(policy["tx_type"], "0x25");
        assert_eq!(policy["protocol_active"], true);
        assert_eq!(policy["issuance_ready"], false);
        assert!(policy["readiness_unavailable_reason"].is_string());
        assert!(policy["recovery_epoch"].is_null());
        assert!(policy["validator_set_id"].is_null());
        assert!(policy["transaction_domain"].is_null());
        assert_eq!(approval["locally_approved"], false);
        assert_eq!(approval["submitted"], false);
        assert!(approval["recovery_epoch"].is_null());
        assert!(approval["validator_set_id"].is_null());
    }

    #[tokio::test]
    async fn stake_zero_canonical_worker_claim_result_quorum_and_mined_reward_end_to_end() {
        use arc_types::transaction::{
            CommunityInferenceRewardBody, CommunityRewardValidatorApproval,
            InferenceAttestationBody, WorkerInferenceCertificate,
        };

        let validators: Vec<_> = (0..6)
            .map(|_| arc_crypto::KeyPair::generate_ed25519())
            .collect();
        let worker = arc_crypto::KeyPair::generate_ed25519();
        let treasury = arc_types::transaction::inference_reward_treasury_address();
        let reward_amount = arc_types::economics::INFERENCE_ATTESTATION_REWARD;
        let state = arc_state::StateDB::with_genesis(&[
            (treasury, reward_amount * 2),
            (worker.address(), 0),
        ]);
        state.seed_genesis_validators(
            &validators
                .iter()
                .map(|key| (key.address(), arc_state::StateDB::MIN_VALIDATOR_STAKE))
                .collect::<Vec<_>>(),
        );
        state.set_community_rewards_v1_activation_height(Some(0));
        assert_eq!(state.get_validator_stake(&worker.address()).unwrap_or(0), 0);
        assert!(
            !state.is_validator(&worker.address()),
            "the rewarded compute provider must remain a stake-zero community worker"
        );

        let model_id = arc_crypto::hash_bytes(b"exact-model-artifact");
        let input = "ARC probe";
        let input_hash = arc_crypto::hash_bytes(input.as_bytes());

        // A full-loader worker is explicitly reduced to the same canonical
        // profile as the validator fleet's merged ranges. Prove the exact
        // generated token bytes/hash survive independent recomputation before
        // constructing any reward certificate.
        let mut worker_model = test_reward_inference_model();
        worker_model.enable_i16();
        worker_model.enforce_canonical_i8_profile();
        let validator_model = test_reward_inference_model();
        let prompt = [3, 4];
        let (worker_tokens, worker_hash) = worker_model.generate(&prompt, 1, &[]);
        let (validator_tokens, validator_hash) = validator_model.generate(&prompt, 1, &[]);
        assert_eq!(worker_tokens, validator_tokens);
        assert_eq!(worker_hash, validator_hash);
        let decoded = worker_model.decode(&worker_tokens);
        let mut result = WorkResult {
            job_id: "profile-proof".to_string(),
            worker_id: format!("0x{}", worker.address().to_hex()),
            success: true,
            declined: false,
            output: decoded.clone(),
            output_hash: format!("0x{}", worker_hash.to_hex()),
            tokens_generated: worker_tokens.len() as u64,
            total_ms: 1,
            ms_per_token: 1,
            engine: arc_inference::cached_integer_model::CANONICAL_REWARD_INFERENCE_PROFILE
                .to_string(),
            error: None,
            signed_attestation_hex: None,
        };
        validate_community_reward_profile(&result).unwrap();
        let output_hash =
            compare_community_result_with_tokens(&result, &validator_tokens, &decoded).unwrap();

        // The verifier also requires the complete range/position grid to
        // carry two distinct active-validator signatures out of all three
        // contacted replicas. This synthetic one-range proof isolates that
        // authorization invariant from HTTP timing.
        let pipeline = vec![(
            (0, 1),
            vec![
                shard("validator-0", "10.0.0.1:9090", 0, 1),
                shard("validator-1", "10.0.0.2:9090", 0, 1),
                shard("validator-2", "10.0.0.3:9090", 0, 1),
            ],
        )];
        let hop_stats = vec![HopStats {
            positions: 1,
            ..HopStats::default()
        }];
        let votes = vec![RangeVote {
            position: 0,
            range: (0, 1),
            replicas_contacted: vec![
                "validator-0".into(),
                "validator-1".into(),
                "validator-2".into(),
            ],
            replicas_returned: vec!["validator-0".into(), "validator-1".into()],
            majority_hash: Some(worker_hash.to_hex()),
            majority_token_id: Some(3),
            majority_signers: vec![validators[0].address(), validators[1].address()],
            divergent: Vec::new(),
            agreement: "majority".into(),
        }];
        let active = validators
            .iter()
            .map(|key| (key.address(), arc_state::StateDB::MIN_VALIDATOR_STAKE))
            .collect::<Vec<_>>();
        assert_eq!(
            validate_community_range_position_quorums(&pipeline, &hop_stats, &votes, &active,)
                .unwrap(),
            1
        );
        let mut worker_attestation = arc_types::Transaction {
            tx_type: arc_types::TxType::InferenceAttestation,
            from: worker.address(),
            nonce: 0,
            body: arc_types::TxBody::InferenceAttestation(InferenceAttestationBody {
                model_id,
                input_hash,
                output_hash,
                challenge_period: 100,
                bond: 0,
                beneficiary: None,
            }),
            fee: 0,
            gas_limit: 0,
            hash: Hash256::ZERO,
            signature: arc_crypto::Signature::null(),
            sig_verified: false,
        };
        worker_attestation.sign(&worker).unwrap();
        let assignment_epoch = arc_crypto::hash_bytes(b"coordinator-recovery-epoch");
        let job_nonce = 17;
        let job_id = CommunityInferenceRewardBody::derive_job_id(
            &validators[0].address(),
            &assignment_epoch,
            job_nonce,
            &model_id,
            &input_hash,
            32,
        );
        let job_id_hex = format!("0x{}", job_id.to_hex());
        result.job_id = job_id_hex.clone();

        // Exercise the actual community assignment boundary for this same
        // eventual reward job. Validator shard compute has a dedicated
        // semaphore; even when every seed-owned shard permit is occupied, a
        // registered stake-zero worker must still receive its bounded queue
        // assignment with the exact canonical profile and artifact identity.
        let registered_worker = CommunityWorker {
            worker_id: result.worker_id.clone(),
            name: "stake-zero-canonical-worker".to_string(),
            capabilities: vec!["inference".to_string()],
            model: Some("exact-model-artifact".to_string()),
            model_id: Some(format!("0x{}", model_id.to_hex())),
            execution_profile: Some(
                arc_inference::cached_integer_model::CANONICAL_REWARD_INFERENCE_PROFILE.to_string(),
            ),
            platform: "test".to_string(),
            registered_at: 0,
            work_completed: 0,
            success_count: 0,
            failure_count: 0,
            sum_total_ms_success: 0,
            last_total_ms: 0,
        };
        let dispatch_node =
            fake_node_with_workers(vec![(registered_worker, std::time::Instant::now())]);
        let held_seed_shard_permits = dispatch_node
            .validator_shard_permits
            .clone()
            .acquire_many_owned(VALIDATOR_SHARD_CONCURRENCY as u32)
            .await
            .unwrap();
        assert_eq!(dispatch_node.validator_shard_permits.available_permits(), 0);
        let assigned_item = WorkItem {
            job_id: job_id_hex.clone(),
            input: input.to_string(),
            max_tokens: 32,
            model_id: Some(format!("0x{}", model_id.to_hex())),
            execution_profile:
                arc_inference::cached_integer_model::CANONICAL_REWARD_INFERENCE_PROFILE.to_string(),
            transaction_domain: None,
            submitted_at_unix_ms: 1,
            expires_at_unix_ms: u64::MAX,
        };
        let _assignment_receiver = insert_pending_job(&dispatch_node, assigned_item.clone(), None);
        dispatch_node
            .community_work_tx
            .as_ref()
            .unwrap()
            .send(assigned_item.clone())
            .await
            .unwrap();
        let Json(claimed) = tokio::time::timeout(
            std::time::Duration::from_millis(100),
            community_claim_work(
                AxumState(dispatch_node.clone()),
                Json(ClaimWorkRequest {
                    worker_id: result.worker_id.clone(),
                    capabilities: vec!["inference".to_string()],
                    model_id: format!("0x{}", model_id.to_hex()),
                    execution_profile:
                        arc_inference::cached_integer_model::CANONICAL_REWARD_INFERENCE_PROFILE
                            .to_string(),
                }),
            ),
        )
        .await
        .expect("community assignment cannot wait for seed shard capacity")
        .unwrap();
        assert_eq!(claimed["status"], "work");
        assert_eq!(claimed["job_id"], assigned_item.job_id);
        assert_eq!(claimed["input"], input);
        assert_eq!(
            claimed["execution_profile"],
            arc_inference::cached_integer_model::CANONICAL_REWARD_INFERENCE_PROFILE
        );
        assert_eq!(
            dispatch_node
                .community_work_results
                .as_ref()
                .unwrap()
                .get(&job_id_hex)
                .unwrap()
                .assigned_worker
                .as_deref(),
            Some(result.worker_id.as_str())
        );
        drop(held_seed_shard_permits);

        let mut body = CommunityInferenceRewardBody {
            chain_domain: CommunityInferenceRewardBody::expected_chain_domain(),
            job_id,
            coordinator: validators[0].address(),
            assignment_epoch,
            job_nonce,
            recovery_epoch: 0,
            validator_set_id: 0,
            transaction_domain: Hash256::ZERO,
            worker: worker.address(),
            model_id,
            input_hash,
            output_hash,
            max_tokens: 32,
            expires_at_height: 100,
            worker_certificate: WorkerInferenceCertificate {
                attestation_hash: worker_attestation.hash,
                nonce: worker_attestation.nonce,
                challenge_period: 100,
                signature: worker_attestation.signature.clone(),
            },
            validator_approvals: Vec::new(),
        };
        let commitment = body.validator_approval_commitment();
        body.validator_approvals = validators[..5]
            .iter()
            .map(|key| {
                CommunityRewardValidatorApproval::from_ed25519_signature(
                    key.address(),
                    key.sign(&commitment).unwrap(),
                )
                .unwrap()
            })
            .collect();
        let approval_body = body.clone();
        let mut reward = arc_types::Transaction::new_community_inference_reward(
            validators[0].address(),
            job_nonce,
            body,
        );
        reward.sign(&validators[0]).unwrap();
        let tx_hash = reward.hash;
        let (_, receipts) = state
            .execute_block(&[reward], validators[0].address())
            .unwrap();
        assert!(receipts[0].success);

        let mut node = fake_node_with_workers(Vec::new());
        node.state = Arc::new(state);
        node.inference_results.insert(
            format!("0x{}", job_id.to_hex()),
            json!({
                "input": "private prompt must be scrubbed",
                "output": "private output must be scrubbed",
                "tokens_generated": 1,
                "observed_at_unix_ms": 1_787_857_623_000u64,
                "nested": {"prompt": "also private"},
            }),
        );
        let accepted = validate_collected_reward_approvals(
            &node,
            &approval_body,
            approval_body.validator_approvals.clone(),
        )
        .expect("five independently signed approvals satisfy the six-validator policy");
        assert_eq!(accepted.len(), 5);
        let four = approval_body.validator_approvals[..4].to_vec();
        let shortfall = validate_collected_reward_approvals(&node, &approval_body, four)
            .expect_err("four of six must fail closed");
        assert!(shortfall.contains("5 of 6 required"), "{shortfall}");
        let duplicate_identity = vec![approval_body.validator_approvals[0].clone(); 5];
        let duplicate_error =
            validate_collected_reward_approvals(&node, &approval_body, duplicate_identity)
                .expect_err("repeating one validator identity cannot manufacture 5-of-6");
        assert!(duplicate_error.contains("1 valid independent approvals"));
        let mut changed_commitment = approval_body.clone();
        changed_commitment.output_hash = arc_crypto::hash_bytes(b"stale-other-output");
        let stale_error = validate_collected_reward_approvals(
            &node,
            &changed_commitment,
            approval_body.validator_approvals.clone(),
        )
        .expect_err("approvals for an older result commitment must be rejected");
        assert!(stale_error.contains("0 valid independent approvals"));

        // Recovery retries must not let responder timing choose different
        // five-of-six evidence and therefore a different outer tx hash.
        let mut recovery_body = approval_body.clone();
        let mut probe_id = [0u8; 32];
        probe_id[..arc_types::transaction::RECOVERY_REWARD_PROBE_PREFIX.len()]
            .copy_from_slice(&arc_types::transaction::RECOVERY_REWARD_PROBE_PREFIX);
        probe_id[arc_types::transaction::RECOVERY_REWARD_PROBE_PREFIX.len()..].fill(5);
        recovery_body.assignment_epoch = Hash256(probe_id);
        recovery_body.job_id = CommunityInferenceRewardBody::derive_job_id(
            &recovery_body.coordinator,
            &recovery_body.assignment_epoch,
            recovery_body.job_nonce,
            &recovery_body.model_id,
            &recovery_body.input_hash,
            recovery_body.max_tokens,
        );
        recovery_body.validator_approvals.clear();
        let recovery_commitment = recovery_body.validator_approval_commitment();
        let all_recovery_approvals: Vec<_> = validators
            .iter()
            .map(|validator| {
                CommunityRewardValidatorApproval::from_ed25519_signature(
                    validator.address(),
                    validator.sign(&recovery_commitment).unwrap(),
                )
                .unwrap()
            })
            .collect();
        let mut reversed = all_recovery_approvals.clone();
        reversed.reverse();
        let canonical_first = validate_collected_reward_approvals(
            &node,
            &recovery_body,
            all_recovery_approvals.clone(),
        )
        .unwrap();
        let canonical_retry =
            validate_collected_reward_approvals(&node, &recovery_body, reversed).unwrap();
        assert_eq!(
            bincode::serialize(&canonical_first).unwrap(),
            bincode::serialize(&canonical_retry).unwrap(),
            "recovery approval bytes cannot depend on response order"
        );
        let mut expected_addresses: Vec<_> = validators.iter().map(|key| key.address()).collect();
        expected_addresses.sort_unstable_by_key(|address| address.0);
        expected_addresses.truncate(5);
        assert_eq!(
            canonical_first
                .iter()
                .map(|approval| approval.validator)
                .collect::<Vec<_>>(),
            expected_addresses
        );
        let missing_canonical = all_recovery_approvals
            .into_iter()
            .filter(|approval| approval.validator != expected_addresses[0])
            .collect();
        let missing = validate_collected_reward_approvals(&node, &recovery_body, missing_canonical)
            .expect_err("a noncanonical five cannot change the recovery transaction");
        assert!(missing.contains("canonical address-sorted"), "{missing}");
        let Json(earnings) = worker_earnings(
            AxumState(node.clone()),
            axum::extract::Path(format!("0x{}", worker.address().to_hex())),
        )
        .await
        .unwrap();
        assert_eq!(earnings["confirmed_receipt_count"], 1);
        assert_eq!(earnings["confirmed_receipts"][0]["tx_type"], "0x25");
        assert_eq!(earnings["confirmed_gross_earnings_base"], reward_amount);
        assert!(earnings["projected_daily_arc"].is_null());
        assert!(earnings["projected_daily_unavailable_reason"].is_string());

        let Json(receipt) = community_reward_receipt(
            AxumState(node.clone()),
            axum::extract::Path(format!("0x{}", tx_hash.to_hex())),
        )
        .await
        .unwrap();
        assert_eq!(receipt["status"], "mined_success");
        assert_eq!(receipt["submitted"], true);
        assert_eq!(receipt["included"], true);
        assert_eq!(receipt["confirmed"], true);
        assert_eq!(receipt["success"], true);
        assert_eq!(
            receipt["receipt_url"],
            format!("/community/reward_receipt/0x{}", tx_hash.to_hex())
        );
        assert_eq!(receipt["reward_base"], reward_amount);
        assert_eq!(receipt["recovery_epoch"], 0);
        assert_eq!(receipt["validator_set_id"], 0);
        assert_eq!(
            receipt["transaction_domain"],
            format!("0x{}", Hash256::ZERO.to_hex())
        );

        let Json(activity) = inference_list_attestations(
            AxumState(node.clone()),
            Query(HashMap::from([("limit".to_string(), "20".to_string())])),
        )
        .await
        .unwrap();
        assert_eq!(activity["paid_success_count"], 1);
        assert_eq!(activity["observation_count"], 0);
        assert_eq!(activity["activities"].as_array().unwrap().len(), 1);
        let paid = activity["activities"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["tx_hash"] == format!("0x{}", tx_hash.to_hex()))
            .expect("successful 0x25 receipt is visible as inference activity");
        assert_eq!(paid["record_kind"], "mined_community_inference_reward");
        assert_eq!(paid["tx_type_code"], "0x25");
        assert_eq!(paid["worker"], format!("0x{}", worker.address().to_hex()));
        assert_eq!(paid["submitted"], true);
        assert_eq!(paid["included"], true);
        assert_eq!(paid["confirmed"], true);
        assert_eq!(paid["success"], true);
        assert_eq!(paid["block_height"], receipt["block_height"]);
        assert_eq!(paid["block_hash"], receipt["block_hash"]);
        assert_eq!(paid["index"], receipt["index"]);
        assert_eq!(
            paid["receipt_url"],
            format!("/community/reward_receipt/0x{}", tx_hash.to_hex())
        );
        assert_eq!(paid["reward_base"], reward_amount);
        assert_eq!(paid["reward_arc"], REWARD_PER_ATTESTATION_ARC);
        assert_eq!(paid["computed"], true);
        assert_eq!(paid["paid"], true);
        assert_eq!(paid["earned"], true);
        assert_eq!(paid["payment"]["receipt_backed"], true);
        assert_eq!(paid["inference"]["tokens_generated"], 1);
        assert!(paid["inference"]["input"].is_null());
        assert!(paid["inference"]["output"].is_null());
        assert!(paid["inference"]["nested"]["prompt"].is_null());
        assert!(
            activity["attestations"]
                .as_array()
                .unwrap()
                .iter()
                .any(|row| row["tx_hash"] == paid["tx_hash"])
        );

        node.state.receipts.get_mut(&tx_hash.0).unwrap().success = false;
        let Json(failed_activity) = inference_list_attestations(
            AxumState(node.clone()),
            Query(HashMap::from([("limit".to_string(), "20".to_string())])),
        )
        .await
        .unwrap();
        let failed_paid = failed_activity["activities"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["tx_hash"] == format!("0x{}", tx_hash.to_hex()))
            .expect("failed 0x25 receipt remains visible without being called earned");
        assert_eq!(failed_paid["submitted"], true);
        assert_eq!(failed_paid["included"], true);
        assert_eq!(failed_paid["confirmed"], false);
        assert_eq!(failed_paid["success"], false);
        assert_eq!(failed_paid["paid"], false);
        assert_eq!(failed_paid["earned"], false);
        assert_eq!(
            failed_paid["receipt_url"],
            format!("/community/reward_receipt/0x{}", tx_hash.to_hex())
        );
        assert!(failed_paid["reward_base"].is_null());
        assert!(failed_paid["reward_arc"].is_null());
        assert!(failed_paid["payment"]["reward_base"].is_null());
        assert!(failed_paid["payment"]["reward_arc"].is_null());
        node.state.receipts.get_mut(&tx_hash.0).unwrap().success = true;

        let Json(by_job) = community_reward_job(
            AxumState(node),
            axum::extract::Path(format!("0x{}", job_id.to_hex())),
        )
        .await
        .unwrap();
        assert_eq!(by_job["tx_hash"], format!("0x{}", tx_hash.to_hex()));
        assert_eq!(by_job["submitted"], true);
        assert_eq!(by_job["included"], true);
        assert_eq!(by_job["confirmed"], true);
        assert_eq!(by_job["success"], true);
        assert_eq!(
            by_job["receipt_url"],
            format!("/community/reward_receipt/0x{}", tx_hash.to_hex())
        );
    }

    #[tokio::test]
    async fn remote_approval_endpoint_recomputes_canonical_worker_and_collects_five_payloads() {
        use arc_state::recovery::{
            ArcCheckpoint, RecoveryExportSpec, RecoveryImport, RecoveryNetworkPolicy,
            RecoveryValidator,
        };
        use arc_types::transaction::{
            CommunityInferenceRewardBody, InferenceAttestationBody, JoinValidatorBody,
            WorkerInferenceCertificate,
        };

        let validator_keys: Vec<_> = (0..6)
            .map(|_| arc_crypto::KeyPair::generate_ed25519())
            .collect();
        let legacy_keys: Vec<_> = (0..8)
            .map(|_| arc_crypto::KeyPair::generate_ed25519())
            .collect();
        let worker = arc_crypto::KeyPair::generate_ed25519();
        let treasury = arc_types::transaction::inference_reward_treasury_address();
        let reward_amount = arc_types::economics::INFERENCE_ATTESTATION_REWARD;
        let mut prefunded = vec![
            (treasury, reward_amount * 2),
            (worker.address(), 0),
            (arc_state::recovery::recovery_stake_reserve_address(), 0),
        ];
        prefunded.extend(legacy_keys.iter().map(|key| (key.address(), 5_000_000)));
        let source = arc_state::StateDB::with_genesis(&prefunded);
        let joins = legacy_keys
            .iter()
            .map(|key| {
                let mut transaction = Transaction {
                    tx_type: TxType::JoinValidator,
                    from: key.address(),
                    nonce: 0,
                    body: TxBody::JoinValidator(JoinValidatorBody {
                        pubkey: key.public_key_bytes().try_into().unwrap(),
                        initial_stake: 5_000_000,
                    }),
                    fee: 0,
                    gas_limit: 0,
                    hash: Hash256::ZERO,
                    signature: arc_crypto::Signature::null(),
                    sig_verified: false,
                };
                transaction.sign(key).unwrap();
                transaction
            })
            .collect::<Vec<_>>();
        let (_, join_receipts) = source
            .execute_block(&joins, legacy_keys[0].address())
            .unwrap();
        assert!(join_receipts.iter().all(|receipt| receipt.success));
        // Production legacy validator weight lives in the validator map while
        // the explicit system reserve carries its fungible backing. Recreate
        // that unambiguous decomposition instead of exporting overloaded
        // per-account staked_balance fields.
        for key in &legacy_keys {
            let mut account = source.get_account(&key.address()).unwrap();
            account.staked_balance = 0;
            source.update_account(&key.address(), account);
        }
        let reserve_address = arc_state::recovery::recovery_stake_reserve_address();
        let mut reserve = source.get_account(&reserve_address).unwrap();
        reserve.balance = 40_000_000;
        source.update_account(&reserve_address, reserve);
        source
            .execute_block(&[], legacy_keys[0].address())
            .expect("reserve decomposition must have a canonical source boundary");

        let target_validators = validator_keys
            .iter()
            .enumerate()
            .map(|(index, key)| RecoveryValidator {
                address: key.address(),
                public_key: key.public_key_bytes().try_into().unwrap(),
                stake: 6_666_666 + u64::from(index < 4),
            })
            .collect::<Vec<_>>();
        let genesis_hash = arc_crypto::hash_bytes(b"remote-approval-endpoint-genesis");
        let mut checkpoint = ArcCheckpoint::export_unsigned(
            &source,
            RecoveryExportSpec {
                chain_id: "arc-remote-approval-test".to_string(),
                genesis_hash,
                source_consensus_round: 1,
                recovery_epoch: 7,
                validator_set_id: 9,
                validators: target_validators.clone(),
                community_rewards_v1_activation_height: Some(0),
                created_at_unix_ms: 1,
            },
        )
        .unwrap();
        for key in validator_keys.iter().take(5) {
            checkpoint.add_signature(key).unwrap();
        }
        let approved_manifest_hash = checkpoint.manifest_hash();
        let temporary = std::env::temp_dir().join(format!(
            "arc-remote-approval-endpoint-{}",
            uuid::Uuid::new_v4()
        ));
        std::fs::create_dir(&temporary).unwrap();
        let checkpoint_path = temporary.join("approved.arcchkpt");
        checkpoint.write_to(&checkpoint_path).unwrap();
        let data_dir = temporary.join("recovered");
        let policy = RecoveryNetworkPolicy {
            chain_id: "arc-remote-approval-test".to_string(),
            genesis_hash,
            recovery_epoch: 7,
            validator_set_id: 9,
            validators: target_validators
                .iter()
                .map(|validator| (validator.address, validator.stake))
                .collect(),
            community_rewards_v1_activation_height: Some(0),
        };
        let recovered = Arc::new(
            arc_state::StateDB::with_genesis_persistent_recovery(
                &[],
                &data_dir,
                policy,
                Some(RecoveryImport {
                    checkpoint_path,
                    approved_manifest_hash,
                }),
            )
            .unwrap(),
        );
        let active = recovered.active_validators();
        assert_eq!(active.len(), 6);

        let model_id = arc_crypto::hash_bytes(b"remote-approval-exact-model");
        let model = Arc::new(test_reward_inference_model());
        let model_name = model_display_name(&model);
        let mut shard_nodes = Vec::new();
        let mut shard_handles = Vec::new();
        let mut replicas = Vec::new();
        for (index, key) in validator_keys.iter().take(3).enumerate() {
            let mut node = fake_node_with_workers(Vec::new());
            node.state = recovered.clone();
            node.validator_address = key.address();
            node.validator_keypair = Some(Arc::new(key.clone()));
            node.inference_model = Some(model.clone());
            node.model_artifact_id = Some(model_id);
            *node.dag_validators.write() = active.clone();
            node.shard_infos = vec![ShardInfo {
                start_layer: 0,
                end_layer: 1,
                total_layers: 1,
                model_id: format!("0x{}", model_id.to_hex()),
                model_name: model_name.clone(),
                execution_profile: canonical_profile(),
                memory_mb: 1,
                full_model_mb: 1,
                socket_addr: String::new(),
                node_name: format!("shard-{index}"),
            }];
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
            let origin = format!("http://{}", listener.local_addr().unwrap());
            let app = Router::new()
                .route("/network/info", get(network_info))
                .route("/inference/forward_shard", post(inference_forward_shard))
                .route("/inference/cleanup_shard", post(inference_cleanup_shard))
                .with_state(node.clone());
            shard_handles.push(tokio::spawn(async move {
                axum::serve(listener, app).await.unwrap();
            }));
            replicas.push(ShardInfo {
                socket_addr: origin,
                ..node.shard_infos[0].clone()
            });
            shard_nodes.push(node);
        }
        let pipeline = vec![((0, 1), replicas)];

        let input = "ARC";
        let worker_prompt = model.encode(input);
        let (output_tokens, output_hash) = model.generate(&worker_prompt, 1, &[]);
        assert_eq!(output_tokens.len(), 1);
        let output = model.decode(&output_tokens);
        let input_hash = arc_crypto::hash_bytes(input.as_bytes());
        let mut worker_attestation = Transaction {
            tx_type: TxType::InferenceAttestation,
            from: worker.address(),
            nonce: 0,
            body: TxBody::InferenceAttestation(InferenceAttestationBody {
                model_id,
                input_hash,
                output_hash,
                challenge_period: 100,
                bond: 0,
                beneficiary: None,
            }),
            fee: 0,
            gas_limit: 0,
            hash: Hash256::ZERO,
            signature: arc_crypto::Signature::null(),
            sig_verified: false,
        };
        worker_attestation
            .sign_in_domain(
                &worker,
                &recovered.recovery_context().unwrap().domain_hash(),
            )
            .unwrap();
        let assignment_epoch = arc_crypto::hash_bytes(b"remote-approval-assignment");
        let job_nonce = 23;
        let job_id = CommunityInferenceRewardBody::derive_job_id(
            &validator_keys[0].address(),
            &assignment_epoch,
            job_nonce,
            &model_id,
            &input_hash,
            1,
        );
        let context = recovered.recovery_context().unwrap();
        let reward = CommunityInferenceRewardBody {
            chain_domain: CommunityInferenceRewardBody::expected_chain_domain(),
            job_id,
            coordinator: validator_keys[0].address(),
            assignment_epoch,
            job_nonce,
            recovery_epoch: context.recovery_epoch,
            validator_set_id: context.validator_set_id,
            transaction_domain: context.domain_hash(),
            worker: worker.address(),
            model_id,
            input_hash,
            output_hash,
            max_tokens: 1,
            expires_at_height: recovered.height() + COMMUNITY_REWARD_EXPIRY_BLOCKS,
            worker_certificate: WorkerInferenceCertificate {
                attestation_hash: worker_attestation.hash,
                nonce: worker_attestation.nonce,
                challenge_period: 100,
                signature: worker_attestation.signature.clone(),
            },
            validator_approvals: Vec::new(),
        };
        let payload = CommunityRewardApprovalPayload {
            coordinator_id: format!("0x{}", validator_keys[0].address().to_hex()),
            reward: reward.clone(),
            input: input.to_string(),
            output,
            tokens_generated: output_tokens.len() as u64,
            execution_profile: canonical_profile(),
        };

        // Approval ingress must reject a tokenizer-expanded context before it
        // acquires either bounded queue or recomputation capacity. With two
        // prompt-side positions and max_seq=32, max_tokens=31 requires 34
        // positions and is deliberately one-or-more beyond the model window.
        let mut oversized_payload = payload.clone();
        oversized_payload.reward.max_tokens = 31;
        oversized_payload.reward.job_id = CommunityInferenceRewardBody::derive_job_id(
            &oversized_payload.reward.coordinator,
            &oversized_payload.reward.assignment_epoch,
            oversized_payload.reward.job_nonce,
            &oversized_payload.reward.model_id,
            &oversized_payload.reward.input_hash,
            oversized_payload.reward.max_tokens,
        );
        let mut preflight_approver = fake_node_with_workers(Vec::new());
        preflight_approver.state = recovered.clone();
        preflight_approver.validator_address = validator_keys[1].address();
        preflight_approver.validator_keypair = Some(Arc::new(validator_keys[1].clone()));
        preflight_approver.community_rewards_v1_enabled = true;
        preflight_approver.inference_model = Some(model.clone());
        preflight_approver.model_artifact_id = Some(model_id);
        preflight_approver.community_rpc_bases = Arc::new(
            (1..=5)
                .map(|index| format!("http://127.0.0.{index}:1"))
                .collect(),
        );
        *preflight_approver.dag_validators.write() = active.clone();
        preflight_approver.community_verification_pipeline_override = Some(pipeline.clone());
        let queue_before = preflight_approver
            .community_approval_queue_permits
            .available_permits();
        let compute_before = preflight_approver
            .community_approval_permits
            .available_permits();
        let oversized_signed = super::sign_community_request(
            COMMUNITY_REWARD_APPROVE_PATH,
            oversized_payload,
            &validator_keys[0],
            preflight_approver.validator_address,
            preflight_approver.state.transaction_domain_hash(),
        )
        .unwrap();
        let oversized_error = community_reward_approve_signed(
            AxumState(preflight_approver.clone()),
            Json(oversized_signed),
        )
        .await
        .expect_err("oversized approval context is rejected before recomputation");
        assert_eq!(oversized_error.0, StatusCode::UNPROCESSABLE_ENTITY);
        assert!(oversized_error.1.contains("context_window_exceeded"));
        assert_eq!(
            preflight_approver
                .community_approval_queue_permits
                .available_permits(),
            queue_before
        );
        assert_eq!(
            preflight_approver
                .community_approval_permits
                .available_permits(),
            compute_before
        );
        assert!(preflight_approver.shard_kv_caches.is_empty());

        for shard_node in &shard_nodes {
            shard_node.shard_kv_caches.clear();
            shard_node.shard_kv_cache_metadata.clear();
        }
        // Production approval collection starts all five remote validators
        // while the same three shard holders are busy. This is the regression
        // that used to fail immediately at the third try_acquire and made
        // five-of-six mathematically unreachable under real fan-out.
        let mut approval_tasks = tokio::task::JoinSet::new();
        for key in validator_keys.iter().skip(1) {
            let key = key.clone();
            let mut approver = fake_node_with_workers(Vec::new());
            approver.state = recovered.clone();
            approver.validator_address = key.address();
            approver.validator_keypair = Some(Arc::new(key.clone()));
            approver.community_rewards_v1_enabled = true;
            approver.inference_model = Some(model.clone());
            approver.model_artifact_id = Some(model_id);
            approver.community_rpc_bases = Arc::new(
                (1..=5)
                    .map(|index| format!("http://127.0.0.{index}:1"))
                    .collect(),
            );
            *approver.dag_validators.write() = active.clone();
            approver.community_verification_pipeline_override = Some(pipeline.clone());
            let signed = super::sign_community_request(
                COMMUNITY_REWARD_APPROVE_PATH,
                payload.clone(),
                &validator_keys[0],
                approver.validator_address,
                approver.state.transaction_domain_hash(),
            )
            .unwrap();
            approval_tasks.spawn(async move {
                let Json(approval) =
                    community_reward_approve_signed(AxumState(approver), Json(signed))
                        .await
                        .expect("parallel endpoint authenticates, queues, recomputes, and signs");
                approval
            });
        }
        let mut approvals = Vec::new();
        while let Some(approval) = approval_tasks.join_next().await {
            approvals.push(approval.expect("parallel approval task joins"));
        }
        assert_eq!(approvals.len(), 5);
        let mut coordinator = fake_node_with_workers(Vec::new());
        coordinator.state = recovered;
        let collected =
            validate_collected_reward_approvals(&coordinator, &reward, approvals).unwrap();
        assert_eq!(collected.len(), 5);

        for handle in shard_handles {
            handle.abort();
        }
        drop(coordinator);
        let _ = std::fs::remove_dir_all(temporary);
    }

    #[tokio::test]
    async fn work_queue_round_trip_after_serve_wiring() {
        // Smoke test: build_node_state alone leaves the queue None
        // (callers must use serve() to wire it). After we manually wire
        // the channel (mirroring serve()), tx.send → rx.recv works.
        let (tx, rx) = tokio::sync::mpsc::channel::<WorkItem>(8);
        let tx = Arc::new(tx);
        let rx = Arc::new(tokio::sync::Mutex::new(rx));

        // Push one job
        tx.send(WorkItem {
            job_id: "j1".into(),
            input: "ping".into(),
            max_tokens: 4,
            model_id: None,
            execution_profile: canonical_profile(),
            transaction_domain: None,
            submitted_at_unix_ms: 1,
            expires_at_unix_ms: u64::MAX,
        })
        .await
        .unwrap();

        // Drain
        let got = rx.lock().await.recv().await.expect("a job");
        assert_eq!(got.job_id, "j1");
        assert_eq!(got.input, "ping");
    }

    #[tokio::test]
    async fn idle_long_polls_do_not_serialize_workers_behind_receiver_mutex() {
        let (tx, rx) = tokio::sync::mpsc::channel::<WorkItem>(8);
        let queue = Arc::new(tokio::sync::Mutex::new(rx));
        let mut waiters = tokio::task::JoinSet::new();
        for _ in 0..3 {
            let queue = queue.clone();
            waiters.spawn(async move {
                poll_community_work_queue(&queue, std::time::Duration::from_secs(1))
                    .await
                    .unwrap()
                    .expect("one queued job")
                    .job_id
            });
        }
        tokio::task::yield_now().await;
        for id in ["job-a", "job-b", "job-c"] {
            tx.send(WorkItem {
                job_id: id.to_string(),
                input: "prompt".to_string(),
                max_tokens: 1,
                model_id: None,
                execution_profile: canonical_profile(),
                transaction_domain: None,
                submitted_at_unix_ms: 0,
                expires_at_unix_ms: u64::MAX,
            })
            .await
            .unwrap();
        }

        let collected = tokio::time::timeout(std::time::Duration::from_millis(500), async {
            let mut ids = Vec::new();
            while let Some(result) = waiters.join_next().await {
                ids.push(result.unwrap());
            }
            ids.sort();
            ids
        })
        .await
        .expect("all idle workers should receive concurrently");
        assert_eq!(collected, vec!["job-a", "job-b", "job-c"]);
    }

    // ── Smart router (task 2) tests ─────────────────────────────────────
    //
    // These exercise live_inference_worker_count and
    // dispatch_to_community_worker against a node state we wire up by
    // hand — a full serve() boot would pull in axum + listen sockets,
    // which is out of scope for a unit test. We construct just enough of
    // NodeState to drive the router paths.

    use std::sync::atomic::AtomicU32;
    use std::time::Instant;

    fn test_model_id() -> String {
        format!(
            "0x{}",
            arc_crypto::hash_bytes(b"synthetic-model-artifact-exact-bytes").to_hex()
        )
    }

    fn test_inference_model() -> Arc<arc_inference::cached_integer_model::CachedIntegerModel> {
        use arc_inference::cached_integer_model::{CachedIntegerModel, I8Weights, ModelConfig};

        let mut vocab = vec!["<unk>".to_string(), "▁x".to_string()];
        vocab.extend((0u16..=255).map(|byte| format!("<0x{byte:02X}>")));
        Arc::new(CachedIntegerModel {
            config: ModelConfig {
                n_layers: 0,
                d_model: 1,
                n_heads: 1,
                n_kv_heads: 1,
                d_ff: 1,
                d_head: 1,
                d_kv: 1,
                vocab_size: vocab.len(),
                attn_scale: 1,
                rope_cos: Vec::new(),
                rope_sin: Vec::new(),
                max_seq: 512,
                eos_tokens: Vec::new(),
                bos_token: 0,
                chat_template: String::new(),
            },
            embedding_q16: Vec::new(),
            embedding_i8: I8Weights::empty(),
            layers: Vec::new(),
            final_norm: Vec::new(),
            output_weight: I8Weights::empty(),
            vocab,
            q4_layers: None,
            q4_output: None,
            i16_layers: None,
            i16_output: None,
            block_i8_layers: None,
            block_i8_output: None,
            ternary_layers: None,
            ternary_output: None,
            ternary_hybrid_layers: None,
            ternary_hybrid_output: None,
        })
    }

    fn test_reward_inference_model() -> arc_inference::cached_integer_model::CachedIntegerModel {
        use arc_inference::cached_integer_model::{
            CachedIntegerModel, CachedLayer, I8Weights, ModelConfig,
        };

        const ONE: i64 = 1 << 16;
        let d = 4usize;
        let d_ff = 8usize;
        let vocab_size = 8usize;
        let weights = |rows: usize, cols: usize, salt: usize| {
            let values: Vec<f32> = (0..rows * cols)
                .map(|index| (((index + salt) % 11) as f32 - 5.0) / 50.0)
                .collect();
            I8Weights::quantize_f32(&values, rows, cols)
        };
        let embedding_values: Vec<f32> = (0..vocab_size * d)
            .map(|index| (((index + 3) % 13) as f32 - 6.0) / 40.0)
            .collect();
        let embedding_i8 = I8Weights::quantize_f32(&embedding_values, vocab_size, d);
        let embedding_q16 = embedding_values
            .iter()
            .map(|value| (*value * ONE as f32).round() as i64)
            .collect();
        CachedIntegerModel {
            config: ModelConfig {
                n_layers: 1,
                d_model: d,
                n_heads: 1,
                n_kv_heads: 1,
                d_ff,
                d_head: d,
                d_kv: d,
                vocab_size,
                attn_scale: ONE / 2,
                rope_cos: vec![ONE; 64],
                rope_sin: vec![0; 64],
                max_seq: 32,
                eos_tokens: Vec::new(),
                bos_token: 1,
                chat_template: String::new(),
            },
            embedding_q16,
            embedding_i8,
            layers: vec![CachedLayer {
                wq: weights(d, d, 1),
                wk: weights(d, d, 2),
                wv: weights(d, d, 3),
                wo: weights(d, d, 4),
                w_gate: weights(d_ff, d, 5),
                w_up: weights(d_ff, d, 6),
                w_down: weights(d, d_ff, 7),
                attn_norm: vec![ONE; d],
                ffn_norm: vec![ONE; d],
            }],
            final_norm: vec![ONE; d],
            output_weight: weights(vocab_size, d, 8),
            vocab: vec![
                "<unk>".into(),
                "<s>".into(),
                "</s>".into(),
                "▁ARC".into(),
                "probe".into(),
                "ok".into(),
                "yes".into(),
                "done".into(),
            ],
            q4_layers: None,
            q4_output: None,
            i16_layers: None,
            i16_output: None,
            block_i8_layers: None,
            block_i8_output: None,
            ternary_layers: None,
            ternary_output: None,
            ternary_hybrid_layers: None,
            ternary_hybrid_output: None,
        }
    }

    fn context_test_inference_model(
        max_seq: usize,
    ) -> Arc<arc_inference::cached_integer_model::CachedIntegerModel> {
        let mut model = test_reward_inference_model();
        // `encode` prepends SentencePiece's word-boundary marker. Keep the
        // existing eight-row weight shape while making "ARC" exactly one
        // tokenizer token for boundary arithmetic and real tiny inference.
        model.vocab[3] = "▁ARC".to_string();
        model.config.max_seq = max_seq;
        Arc::new(model)
    }

    fn fake_node_with_workers(workers: Vec<(CommunityWorker, std::time::Instant)>) -> NodeState {
        // Build a minimal NodeState by hand. We can't call build_node_state
        // because it requires real Arc<StateDB> and Arc<Mempool>; we only
        // touch fields the router reads.
        let workers_map: dashmap::DashMap<String, (CommunityWorker, std::time::Instant)> =
            dashmap::DashMap::new();
        for (w, ts) in workers {
            workers_map.insert(w.worker_id.clone(), (w, ts));
        }
        let (tx, rx) = tokio::sync::mpsc::channel::<WorkItem>(16);
        NodeState {
            // Fields the router actually reads ↓
            community_workers: Arc::new(workers_map),
            community_registration_gate: Arc::new(parking_lot::Mutex::new(())),
            community_request_replays: Arc::new(parking_lot::Mutex::new(
                CommunityReplayCache::default(),
            )),
            community_validator_request_replays: Arc::new(parking_lot::Mutex::new(
                CommunityReplayCache::validator_domain(),
            )),
            community_reward_approval_jobs: Arc::new(dashmap::DashMap::new()),
            community_reward_approval_certificates: Arc::new(dashmap::DashMap::new()),
            community_reward_submissions: Arc::new(dashmap::DashMap::new()),
            community_verified_settlements: Arc::new(dashmap::DashMap::new()),
            community_verified_settlements_gate: Arc::new(parking_lot::Mutex::new(())),
            community_settlement_journal_dir: None,
            community_work_tx: Some(Arc::new(tx)),
            community_work_queue: Some(Arc::new(tokio::sync::Mutex::new(rx))),
            community_work_results: Some(Arc::new(dashmap::DashMap::new())),
            community_active_jobs: Arc::new(dashmap::DashMap::new()),
            attestation_nonce: Arc::new(AtomicU64::new(0)),
            latency_stats: Arc::new(dashmap::DashMap::new()),

            // Filler ↓ — never read by the router but required by the struct
            state: Arc::new(arc_state::StateDB::new()),
            mempool: Arc::new(arc_mempool::Mempool::new(1_000)),
            validator_address: Hash256::ZERO,
            validator_keypair: None,
            community_rewards_v1_enabled: false,
            stake: 0,
            tier: StakeTier::Spark,
            boot_time: Instant::now(),
            peer_count: Arc::new(AtomicU32::new(0)),
            faucet_claims: Arc::new(dashmap::DashMap::new()),
            faucet_claims_total: Arc::new(AtomicU32::new(0)),
            faucet_pending: Arc::new(tokio::sync::Mutex::new(None)),
            inference_model: Some(test_inference_model()),
            candle_engine: None,
            candle_model_id: None,
            model_artifact_id: parse_hash256_hex(&test_model_id(), "test model_id").ok(),
            dag_validators: Arc::new(parking_lot::RwLock::new(Vec::new())),
            tx_rate_limit: Arc::new(dashmap::DashMap::new()),
            dag_round: Arc::new(AtomicU64::new(0)),
            dag_committed: Arc::new(AtomicU64::new(0)),
            community_job_epoch: arc_crypto::KeyPair::generate_ed25519().address(),
            inference_request_epoch: arc_crypto::KeyPair::generate_ed25519().address(),
            inference_request_counter: Arc::new(AtomicU64::new(0)),
            inference_results: Arc::new(dashmap::DashMap::new()),
            inference_results_gate: Arc::new(parking_lot::Mutex::new(())),
            public_inference_permits: Arc::new(tokio::sync::Semaphore::new(
                PUBLIC_INFERENCE_CONCURRENCY,
            )),
            validator_shard_permits: Arc::new(tokio::sync::Semaphore::new(
                VALIDATOR_SHARD_CONCURRENCY,
            )),
            validator_shard_queue_permits: Arc::new(tokio::sync::Semaphore::new(
                VALIDATOR_SHARD_QUEUE_CAP,
            )),
            community_approval_permits: Arc::new(tokio::sync::Semaphore::new(
                COMMUNITY_APPROVAL_RECOMPUTE_CONCURRENCY,
            )),
            community_approval_queue_permits: Arc::new(tokio::sync::Semaphore::new(
                COMMUNITY_APPROVAL_QUEUE_CAP,
            )),
            shard_infos: Vec::new(),
            shard_kv_caches: Arc::new(dashmap::DashMap::new()),
            shard_kv_cache_metadata: Arc::new(dashmap::DashMap::new()),
            shard_kv_cache_gate: Arc::new(parking_lot::Mutex::new(())),
            shard_rpc_audiences: Arc::new(dashmap::DashMap::new()),
            shard_registry: Arc::new(dashmap::DashMap::new()),
            sharded_runs_total: Arc::new(AtomicU64::new(0)),
            sharded_bytes_total: Arc::new(AtomicU64::new(0)),
            inference_cache: Arc::new(arc_inference::distributed::DistributedCache::new(16)),
            multi_model_registry: Arc::new(arc_inference::distributed::ShardRegistry::new()),
            verification_manager: Arc::new(std::sync::Mutex::new(
                arc_vm::inference_verify::VerificationManager::new(),
            )),
            revenue_config: RoleRevenueConfig::default(),
            inference_http: reqwest::Client::new(),
            sharded_cache_hits: Arc::new(AtomicU64::new(0)),
            sharded_run_meta: Arc::new(dashmap::DashMap::new()),
            compute_pool: Arc::new(parking_lot::RwLock::new(None)),
            compute_threads: Arc::new(AtomicU32::new(0)),
            seed_rpc_addrs: Arc::new(Vec::new()),
            community_rpc_bases: Arc::new(Vec::new()),
            chain_identity: None,
            runtime_shutdown: None,
            runtime_tasks: Arc::new(parking_lot::Mutex::new(tokio::task::JoinSet::new())),
            own_compute_ms: Arc::new(parking_lot::Mutex::new(std::collections::VecDeque::new())),
            community_verification_pipeline_override: None,
        }
    }

    fn worker(id: &str, caps: &[&str]) -> CommunityWorker {
        CommunityWorker {
            worker_id: id.into(),
            name: format!("test-{}", id),
            capabilities: caps.iter().map(|s| s.to_string()).collect(),
            model: Some("arc-0L-1d-1h-2v".into()),
            model_id: Some(test_model_id()),
            execution_profile: Some(canonical_profile()),
            platform: "test".into(),
            registered_at: 0,
            work_completed: 0,
            success_count: 0,
            failure_count: 0,
            sum_total_ms_success: 0,
            last_total_ms: 0,
        }
    }

    #[test]
    fn unsubmitted_reward_states_share_the_exact_no_transaction_matrix() {
        let job_id = format!("0x{}", Hash256([19; 32]).to_hex());
        let worker = format!("0x{}", Hash256([20; 32]).to_hex());
        for status in [
            "reward_protocol_not_activated",
            "reward_approval_quorum_unavailable",
            "missing_worker_attestation",
        ] {
            let settlement =
                unsubmitted_community_reward_settlement(status, &job_id, &worker, "blocked");
            assert_eq!(settlement["status"], status);
            assert_eq!(settlement["tx_type"], "0x25");
            assert!(settlement["tx_hash"].is_null());
            assert_eq!(settlement["job_id"], job_id);
            assert_eq!(settlement["worker"], worker);
            assert_eq!(settlement["submitted"], false);
            assert_eq!(settlement["included"], false);
            assert_eq!(settlement["confirmed"], false);
            assert!(settlement["success"].is_null());
            assert!(settlement["reward_base"].is_null());
            assert!(settlement["reward_arc"].is_null());
            assert!(settlement["receipt_url"].is_null());
        }
    }

    #[tokio::test]
    async fn reward_status_contract_distinguishes_submitted_pending_failed_and_confirmed() {
        let job_id = Hash256([21; 32]);
        let worker_key = arc_crypto::KeyPair::generate_ed25519();
        let worker_hash = worker_key.address();
        let worker_id = format!("0x{}", worker_hash.to_hex());
        let node = fake_node_with_workers(vec![(
            worker(&worker_id, &["inference"]),
            std::time::Instant::now(),
        )]);
        let output_hash = Hash256([23; 32]);
        let signer = arc_crypto::KeyPair::generate_ed25519();
        let mut mempool_tx = Transaction::new_transfer(signer.address(), Hash256([24; 32]), 1, 0);
        mempool_tx.sign(&signer).unwrap();
        let tx_hash = mempool_tx.hash;
        node.mempool.insert(mempool_tx).unwrap();

        let mut payload = test_verified_settlement_payload(job_id, 100);
        payload.reward.worker = worker_hash;
        payload.reward.output_hash = output_hash;
        let recovery_probe_id = payload.reward.assignment_epoch;
        node.community_verified_settlements.insert(
            job_id,
            VerifiedCommunitySettlement {
                payload: payload.clone(),
                verified_at_unix_ms: 1,
                attempts: 1,
                retry_running: false,
                last_error: None,
            },
        );
        let pending_submission = CommunityRewardSubmission {
            worker: worker_hash,
            output_hash,
            tx_hash,
            approvals: 5,
        };
        node.community_reward_submissions
            .insert(job_id, pending_submission.clone());

        let expected_receipt_url = format!("/community/reward_receipt/0x{}", tx_hash.to_hex());
        let pending_from_retry = attempt_verified_community_reward(&node, job_id)
            .await
            .expect("an existing mempool submission is discoverable");
        assert_eq!(pending_from_retry["status"], "pending_mined_receipt");
        assert_eq!(pending_from_retry["submitted"], true);
        assert_eq!(pending_from_retry["included"], false);
        assert_eq!(pending_from_retry["confirmed"], false);
        assert!(pending_from_retry["success"].is_null());
        assert_eq!(pending_from_retry["receipt_url"], expected_receipt_url);

        let Json(pending_by_hash) = community_reward_receipt(
            AxumState(node.clone()),
            axum::extract::Path(format!("0x{}", tx_hash.to_hex())),
        )
        .await
        .unwrap();
        let Json(pending_by_job) = community_reward_job(
            AxumState(node.clone()),
            axum::extract::Path(format!("0x{}", job_id.to_hex())),
        )
        .await
        .unwrap();
        let recovery_replay = recovery_probe_status_response(&node, recovery_probe_id, job_id)
            .unwrap()
            .expect("the recovery replay discovers the same pending submission");
        for pending in [
            &pending_by_hash,
            &pending_by_job,
            &recovery_replay["settlement"],
        ] {
            assert_eq!(pending["status"], "pending_mined_receipt");
            assert_eq!(pending["submitted"], true);
            assert_eq!(pending["included"], false);
            assert_eq!(pending["confirmed"], false);
            assert!(pending["success"].is_null());
            assert_eq!(pending["receipt_url"], expected_receipt_url);
        }

        let pending_result = WorkResult {
            job_id: format!("0x{}", job_id.to_hex()),
            worker_id: worker_id.clone(),
            success: true,
            declined: false,
            output: "pending output".to_string(),
            output_hash: format!("0x{}", output_hash.to_hex()),
            tokens_generated: 1,
            total_ms: 1,
            ms_per_token: 1,
            engine: canonical_profile(),
            error: None,
            signed_attestation_hex: None,
        };
        let Json(pending_submit_replay) =
            community_submit_work(AxumState(node.clone()), Json(pending_result.clone()))
                .await
                .expect("an identical submitted job returns its pending settlement");
        assert_eq!(pending_submit_replay["idempotent_replay"], true);
        assert_eq!(
            pending_submit_replay["settlement"]["job_id"],
            format!("0x{}", job_id.to_hex())
        );
        assert_eq!(pending_submit_replay["settlement"]["worker"], worker_id);
        assert_eq!(pending_submit_replay["settlement"]["submitted"], true);
        assert_eq!(pending_submit_replay["settlement"]["included"], false);
        assert_eq!(pending_submit_replay["settlement"]["confirmed"], false);
        assert!(pending_submit_replay["settlement"]["success"].is_null());
        assert!(pending_submit_replay["settlement"]["reward_base"].is_null());
        assert!(pending_submit_replay["settlement"]["reward_arc"].is_null());
        assert_eq!(
            pending_submit_replay["settlement"]["receipt_url"],
            expected_receipt_url
        );

        // A process-local submission row survives longer than a mempool row.
        // Every public replay/read path must stop calling the old hash
        // submitted once it has neither mempool presence nor chain inclusion,
        // while retaining the durable independently verified job for retry.
        node.mempool.clear();
        let stale_recovery = recovery_probe_status_response(&node, recovery_probe_id, job_id)
            .unwrap()
            .expect("durable verified recovery work remains discoverable");
        let stale_recovery = &stale_recovery["settlement"];
        assert_eq!(stale_recovery["status"], "verified_pending_approval");
        assert_eq!(stale_recovery["submitted"], false);
        assert!(stale_recovery["tx_hash"].is_null());
        assert!(stale_recovery["receipt_url"].is_null());
        assert!(!node.community_reward_submissions.contains_key(&job_id));

        node.community_reward_submissions
            .insert(job_id, pending_submission.clone());
        let Json(stale_submit) =
            community_submit_work(AxumState(node.clone()), Json(pending_result))
                .await
                .expect("idempotent submit falls back to durable verified state");
        assert_eq!(
            stale_submit["settlement"]["status"],
            "verified_pending_approval"
        );
        assert_eq!(stale_submit["settlement"]["submitted"], false);
        assert!(stale_submit["settlement"]["tx_hash"].is_null());

        node.community_reward_submissions
            .insert(job_id, pending_submission.clone());
        let Json(stale_by_hash) = community_reward_receipt(
            AxumState(node.clone()),
            axum::extract::Path(format!("0x{}", tx_hash.to_hex())),
        )
        .await
        .expect("a dropped hash points back to durable verified retry state");
        assert_eq!(stale_by_hash["status"], "verified_pending_approval");
        assert_eq!(stale_by_hash["submitted"], false);
        assert!(stale_by_hash["tx_hash"].is_null());
        assert_eq!(
            stale_by_hash["previous_tx_hash"],
            format!("0x{}", tx_hash.to_hex())
        );

        node.community_reward_submissions
            .insert(job_id, pending_submission);
        let Json(stale_by_job) = community_reward_job(
            AxumState(node.clone()),
            axum::extract::Path(format!("0x{}", job_id.to_hex())),
        )
        .await
        .expect("job lookup retains verified retry state without a fake pending hash");
        assert_eq!(stale_by_job["status"], "verified_pending_approval");
        assert_eq!(stale_by_job["submitted"], false);
        assert!(stale_by_job["tx_hash"].is_null());

        let mut failed_body = payload.reward.clone();
        failed_body.job_id = Hash256([25; 32]);
        let failed_tx = Transaction::new_community_inference_reward(
            failed_body.coordinator,
            failed_body.job_nonce,
            failed_body.clone(),
        );
        let failed_hash = failed_tx.hash;
        let (failed_block, _) = node
            .state
            .execute_block(std::slice::from_ref(&failed_tx), Hash256::ZERO)
            .unwrap();
        node.state.receipts.get_mut(&failed_hash.0).unwrap().success = false;
        let failed_receipt = node.state.get_receipt(&failed_hash.0).unwrap();
        let failed = community_reward_receipt_value(&node, failed_hash)
            .expect("a hash-bound failed receipt has a truthful terminal state");
        assert_eq!(failed["status"], "mined_failed");
        assert_eq!(failed["submitted"], true);
        assert_eq!(failed["included"], true);
        assert_eq!(failed["confirmed"], false);
        assert_eq!(failed["success"], false);
        assert_eq!(failed["block_height"], failed_block.header.height);
        assert_eq!(
            failed["block_hash"],
            format!("0x{}", failed_block.hash.to_hex())
        );
        assert_eq!(failed["index"], 0);
        assert!(failed["reward_base"].is_null());
        assert!(failed["reward_arc"].is_null());
        assert_eq!(
            failed["receipt_url"],
            format!("/community/reward_receipt/0x{}", failed_hash.to_hex())
        );

        let mut corrupt_count_block = failed_block.clone();
        corrupt_count_block.header.tx_count += 1;
        corrupt_count_block.hash = Block::compute_hash(&corrupt_count_block.header);
        assert!(
            validate_canonical_transaction_inclusion(
                &corrupt_count_block,
                failed_block.header.height,
                0,
                failed_hash,
            )
            .unwrap_err()
            .contains("transaction count differs")
        );

        let mut corrupt_root_block = failed_block.clone();
        corrupt_root_block.header.tx_root = Hash256([26; 32]);
        corrupt_root_block.hash = Block::compute_hash(&corrupt_root_block.header);
        assert!(
            validate_canonical_transaction_inclusion(
                &corrupt_root_block,
                failed_block.header.height,
                0,
                failed_hash,
            )
            .unwrap_err()
            .contains("committed Merkle root")
        );

        let mut unavailable_body = payload.reward.clone();
        unavailable_body.job_id = Hash256([27; 32]);
        let unavailable_tx = Transaction::new_community_inference_reward(
            unavailable_body.coordinator,
            unavailable_body.job_nonce,
            unavailable_body.clone(),
        );
        let unavailable_hash = unavailable_tx.hash;
        let (unavailable_block, _) = node
            .state
            .execute_block(std::slice::from_ref(&unavailable_tx), Hash256::ZERO)
            .unwrap();
        node.state.receipts.remove(&unavailable_hash.0);
        let unavailable = community_reward_receipt_value(&node, unavailable_hash)
            .expect("the retained block index proves inclusion without inventing a receipt");
        assert_eq!(unavailable["status"], "receipt_unavailable");
        assert_eq!(unavailable["submitted"], true);
        assert_eq!(unavailable["included"], true);
        assert_eq!(unavailable["confirmed"], false);
        assert!(unavailable["success"].is_null());
        assert_eq!(unavailable["block_height"], unavailable_block.header.height);
        assert_eq!(
            unavailable["block_hash"],
            format!("0x{}", unavailable_block.hash.to_hex())
        );

        // Inclusion can race both retry and idempotent-submit cleanup. A
        // stale submission entry must never mask or resubmit the mined row.
        let race_worker_key = arc_crypto::KeyPair::generate_ed25519();
        let race_worker_id = format!("0x{}", race_worker_key.address().to_hex());
        let race_node = fake_node_with_workers(vec![(
            worker(&race_worker_id, &["inference"]),
            std::time::Instant::now(),
        )]);
        let race_job_id = Hash256([29; 32]);
        let race_output_hash = Hash256([30; 32]);
        let mut race_payload = test_verified_settlement_payload(race_job_id, 100);
        race_payload.reward.worker = race_worker_key.address();
        race_payload.reward.output_hash = race_output_hash;
        let race_body = race_payload.reward.clone();
        let race_tx = Transaction::new_community_inference_reward(
            race_payload.reward.coordinator,
            race_payload.reward.job_nonce,
            race_payload.reward.clone(),
        );
        let race_tx_hash = race_tx.hash;
        race_node
            .state
            .execute_block(std::slice::from_ref(&race_tx), Hash256::ZERO)
            .unwrap();
        race_node
            .state
            .receipts
            .get_mut(&race_tx_hash.0)
            .unwrap()
            .success = true;
        race_node.community_reward_submissions.insert(
            race_job_id,
            CommunityRewardSubmission {
                worker: race_worker_key.address(),
                output_hash: race_output_hash,
                tx_hash: race_tx_hash,
                approvals: 5,
            },
        );
        race_node.community_verified_settlements.insert(
            race_job_id,
            VerifiedCommunitySettlement {
                payload: race_payload,
                verified_at_unix_ms: 1,
                attempts: 1,
                retry_running: false,
                last_error: None,
            },
        );
        let mined_from_retry = attempt_verified_community_reward(&race_node, race_job_id)
            .await
            .expect("retry resolves the mined index before stale mempool bookkeeping");
        assert_eq!(mined_from_retry["status"], "mined_success");
        assert_eq!(mined_from_retry["success"], true);
        assert!(
            race_node
                .community_reward_submissions
                .contains_key(&race_job_id)
        );

        let result = WorkResult {
            job_id: format!("0x{}", race_job_id.to_hex()),
            worker_id: race_worker_id,
            success: true,
            declined: false,
            output: "ok".to_string(),
            output_hash: format!("0x{}", race_output_hash.to_hex()),
            tokens_generated: 1,
            total_ms: 1,
            ms_per_token: 1,
            engine: canonical_profile(),
            error: None,
            signed_attestation_hex: None,
        };
        let Json(mined_submit_replay) =
            community_submit_work(AxumState(race_node.clone()), Json(result.clone()))
                .await
                .expect("a stale submission entry cannot mask successful inclusion");
        assert_eq!(mined_submit_replay["settlement"]["status"], "mined_success");
        assert_eq!(mined_submit_replay["settlement"]["success"], true);

        let later_failed_tx = Transaction::new_community_inference_reward(
            race_body.coordinator,
            race_body.job_nonce + 1,
            race_body,
        );
        let later_failed_hash = later_failed_tx.hash;
        let (_, later_receipts) = race_node
            .state
            .execute_block(std::slice::from_ref(&later_failed_tx), Hash256::ZERO)
            .unwrap();
        assert!(!later_receipts[0].success);
        let selected = indexed_reward_for_job(&race_node, race_job_id)
            .unwrap()
            .expect("the unique successful receipt wins over a later failed replay");
        assert_eq!(selected.0, race_tx_hash);
        race_node
            .state
            .receipts
            .get_mut(&later_failed_hash.0)
            .unwrap()
            .success = true;
        assert!(
            indexed_reward_for_job(&race_node, race_job_id)
                .unwrap_err()
                .contains("multiple successful")
        );
        let duplicate_earnings = worker_earnings(
            AxumState(race_node.clone()),
            axum::extract::Path(format!("0x{}", race_worker_key.address().to_hex())),
        )
        .await
        .expect_err("worker earnings must reject two successful receipts for one job");
        assert_eq!(duplicate_earnings.0, StatusCode::CONFLICT);
        assert!(
            duplicate_earnings
                .1
                .contains("multiple successful 0x25 receipts")
        );
        race_node
            .state
            .receipts
            .get_mut(&later_failed_hash.0)
            .unwrap()
            .success = false;

        race_node
            .state
            .receipts
            .get_mut(&race_tx_hash.0)
            .unwrap()
            .success = false;
        let Json(failed_submit_replay) = community_submit_work(AxumState(race_node), Json(result))
            .await
            .expect("a stale submission entry cannot mask failed inclusion");
        assert_eq!(failed_submit_replay["settlement"]["status"], "mined_failed");
        assert_eq!(failed_submit_replay["settlement"]["success"], false);

        let mut corrupt_receipt = failed_receipt.clone();
        corrupt_receipt.tx_hash = Hash256([28; 32]);
        node.state.receipts.insert(failed_hash.0, corrupt_receipt);
        assert!(
            community_reward_receipt_value(&node, failed_hash)
                .unwrap_err()
                .contains("receipt hash differs")
        );

        let mut corrupt_receipt = failed_receipt.clone();
        corrupt_receipt.block_height = corrupt_receipt.block_height.saturating_add(1);
        node.state.receipts.insert(failed_hash.0, corrupt_receipt);
        assert!(
            community_reward_receipt_value(&node, failed_hash)
                .unwrap_err()
                .contains("block height differs")
        );

        let mut corrupt_receipt = failed_receipt.clone();
        corrupt_receipt.block_hash = Hash256([28; 32]);
        node.state.receipts.insert(failed_hash.0, corrupt_receipt);
        assert!(
            community_reward_receipt_value(&node, failed_hash)
                .unwrap_err()
                .contains("block hash differs")
        );

        let mut corrupt_receipt = failed_receipt.clone();
        corrupt_receipt.index = corrupt_receipt.index.saturating_add(1);
        node.state.receipts.insert(failed_hash.0, corrupt_receipt);
        assert!(
            community_reward_receipt_value(&node, failed_hash)
                .unwrap_err()
                .contains("transaction index differs")
        );
        node.state.receipts.insert(failed_hash.0, failed_receipt);

        node.state
            .full_transactions
            .get_mut(&unavailable_hash.0)
            .unwrap()
            .tx_type = TxType::Transfer;
        assert!(
            indexed_reward_for_job(&node, unavailable_body.job_id)
                .unwrap_err()
                .contains("non-0x25")
        );
        {
            let mut transaction = node
                .state
                .full_transactions
                .get_mut(&unavailable_hash.0)
                .unwrap();
            transaction.tx_type = TxType::CommunityInferenceReward;
            let TxBody::CommunityInferenceReward(body) = &mut transaction.body else {
                panic!("fixture transaction body changed variant")
            };
            body.output_hash = Hash256([31; 32]);
        }
        assert!(
            community_reward_receipt_value(&node, unavailable_hash)
                .unwrap_err()
                .contains("do not reproduce their committed hash"),
            "a mutated reward body retaining its old embedded hash must fail closed"
        );
        let corrupted_earnings = worker_earnings(
            AxumState(node),
            axum::extract::Path(format!("0x{}", worker_hash.to_hex())),
        )
        .await
        .expect_err("matching-worker corruption cannot be silently skipped");
        assert_eq!(corrupted_earnings.0, StatusCode::CONFLICT);
        assert!(
            corrupted_earnings
                .1
                .contains("do not reproduce their committed hash")
        );
    }

    fn community_register_payload(keypair: &arc_crypto::KeyPair) -> CommunityRegisterRequest {
        CommunityRegisterRequest {
            worker_id: format!("0x{}", keypair.address().to_hex()),
            name: "signed test worker".to_string(),
            capabilities: vec!["inference".to_string()],
            model: Some("test-model".to_string()),
            model_id: Some(test_model_id()),
            execution_profile: Some(canonical_profile()),
            platform: "test-platform".to_string(),
        }
    }

    #[tokio::test]
    async fn community_auth_valid_signature_registers_claimed_worker() {
        let keypair = arc_crypto::KeyPair::generate_ed25519();
        let payload = community_register_payload(&keypair);
        let worker_id = payload.worker_id.clone();
        let signed = sign_community_request(COMMUNITY_REGISTER_PATH, payload, &keypair).unwrap();
        let node = fake_node_with_workers(Vec::new());

        let response = community_register_signed(AxumState(node.clone()), Json(signed))
            .await
            .expect("valid proof of possession");

        assert_eq!(response.0["worker_id"], worker_id);
        assert!(node.community_workers.contains_key(&worker_id));
        assert!(
            node.shard_registry.is_empty(),
            "whole-model community registration must never create routable shard targets"
        );
    }

    #[tokio::test]
    async fn inference_registration_requires_an_exact_model_identity() {
        let keypair = arc_crypto::KeyPair::generate_ed25519();
        let mut payload = community_register_payload(&keypair);
        payload.model_id = None;
        let signed = sign_community_request(COMMUNITY_REGISTER_PATH, payload, &keypair).unwrap();
        let node = fake_node_with_workers(Vec::new());

        let error = community_register_signed(AxumState(node.clone()), Json(signed))
            .await
            .expect_err("a human display name alone must never make a worker routable");
        assert_eq!(error.0, StatusCode::BAD_REQUEST);
        assert!(error.1.contains("model_id"));
        assert!(node.community_workers.is_empty());
    }

    #[tokio::test]
    async fn inference_registration_rejects_missing_or_noncanonical_profile_before_work() {
        let node = fake_node_with_workers(Vec::new());

        let missing_key = arc_crypto::KeyPair::generate_ed25519();
        let mut missing = community_register_payload(&missing_key);
        missing.execution_profile = None;
        let missing =
            sign_community_request(COMMUNITY_REGISTER_PATH, missing, &missing_key).unwrap();
        let missing_error = community_register_signed(AxumState(node.clone()), Json(missing))
            .await
            .expect_err("legacy inference registration without a profile must fail closed");
        assert_eq!(missing_error.0, StatusCode::BAD_REQUEST);
        assert!(missing_error.1.contains("execution_profile"));

        let i16_key = arc_crypto::KeyPair::generate_ed25519();
        let mut i16 = community_register_payload(&i16_key);
        i16.execution_profile =
            Some(arc_inference::cached_integer_model::I16_INFERENCE_PROFILE.to_string());
        let i16 = sign_community_request(COMMUNITY_REGISTER_PATH, i16, &i16_key).unwrap();
        let i16_error = community_register_signed(AxumState(node.clone()), Json(i16))
            .await
            .expect_err("noncanonical reward worker registration must fail before dispatch");
        assert_eq!(i16_error.0, StatusCode::CONFLICT);
        assert!(i16_error.1.contains("canonical"));

        assert!(node.community_workers.is_empty());
        assert!(node.community_work_results.as_ref().unwrap().is_empty());
        assert!(node.community_active_jobs.is_empty());
    }

