    #[tokio::test]
    async fn dispatch_to_community_worker_returns_result_when_worker_submits() {
        // Wire a worker: we manually drain the queue and post a result
        // through the same channels submit_work uses, then assert the
        // dispatcher returns the right WorkResult.
        let now = std::time::Instant::now();
        let node = fake_node_with_workers(vec![(worker("w1", &["inference"]), now)]);

        let queue = node.community_work_queue.as_ref().unwrap().clone();
        let results = node.community_work_results.as_ref().unwrap().clone();

        // Spawn a fake worker that drains the queue and posts a result.
        tokio::spawn(async move {
            let item = queue.lock().await.recv().await.expect("a job");
            // submit a successful result
            if let Some((_, pending)) = results.remove(&item.job_id) {
                let _ = pending.sender.send(CommunityDispatchOutcome {
                    result: WorkResult {
                        job_id: item.job_id,
                        worker_id: "w1".into(),
                        success: true,
                        declined: false,
                        output: "4".into(),
                        output_hash: "0xdeadbeef".into(),
                        tokens_generated: 1,
                        total_ms: 50,
                        ms_per_token: 50,
                        engine: "INT8 integer (community worker)".into(),
                        error: None,
                        signed_attestation_hex: None,
                    },
                    verification: Some(CommunityVerificationSummary {
                        method: "authenticated_shard_quorum_2_of_3_per_range",
                        profile_bound: true,
                        quorum_verified: true,
                        execution_profile:
                            arc_inference::cached_integer_model::CANONICAL_REWARD_INFERENCE_PROFILE,
                        output_hash: "0xdeadbeef".to_string(),
                        tokens_generated: 1,
                        ranges: 6,
                        range_position_quorums: 6,
                        signatures_required_per_quorum: 2,
                        replicas_contacted_per_quorum: 3,
                    }),
                    settlement: Some(json!({"status": "test_settlement"})),
                });
            }
        });

        let result =
            dispatch_to_community_worker(&node, "What is 2+2?".into(), 4, Some(test_model_id()))
                .await
                .expect("worker returned a result");

        assert_eq!(result.result.worker_id, "w1");
        assert_eq!(result.result.output, "4");
        assert_eq!(result.result.tokens_generated, 1);
        assert_eq!(
            result.verification.as_ref().unwrap().range_position_quorums,
            6
        );
        assert_eq!(
            result.settlement.as_ref().unwrap()["status"],
            "test_settlement"
        );
        // EWMA was recorded for this worker
        assert!(node.latency_stats.contains_key("worker:w1"));
    }

    #[tokio::test]
    async fn full_community_queue_and_public_inference_flood_fail_fast_and_bounded() {
        let node = fake_node_with_workers(vec![(
            worker("idle-worker", &["inference"]),
            Instant::now(),
        )]);
        for index in 0..16 {
            node.community_work_tx
                .as_ref()
                .unwrap()
                .try_send(WorkItem {
                    job_id: format!("queued-{index}"),
                    input: "queued".to_string(),
                    max_tokens: 1,
                    model_id: Some(test_model_id()),
                    execution_profile: canonical_profile(),
                    transaction_domain: None,
                    submitted_at_unix_ms: 0,
                    expires_at_unix_ms: u64::MAX,
                })
                .unwrap();
        }
        let pending_before = node.community_work_results.as_ref().unwrap().len();
        let failure = tokio::time::timeout(
            std::time::Duration::from_millis(100),
            dispatch_to_community_worker(
                &node,
                "must not wait for a queue slot".to_string(),
                1,
                Some(test_model_id()),
            ),
        )
        .await
        .expect("queue admission is nonblocking")
        .expect_err("a full queue is rejected");
        assert!(failure.contains("queue unavailable"));
        assert_eq!(
            node.community_work_results.as_ref().unwrap().len(),
            pending_before
        );

        let permits: Vec<_> = (0..PUBLIC_INFERENCE_CONCURRENCY)
            .map(|_| {
                node.public_inference_permits
                    .clone()
                    .try_acquire_owned()
                    .unwrap()
            })
            .collect();
        let error = inference_run_sharded(
            AxumState(node.clone()),
            Json(json!({
                "input": "overload",
                "max_tokens": 1,
            })),
        )
        .await
        .expect_err("excess public inference is rejected before spawn_blocking");
        assert_eq!(error.0, StatusCode::TOO_MANY_REQUESTS);
        assert_eq!(node.inference_results.len(), 0);
        assert_eq!(node.community_work_results.as_ref().unwrap().len(), 0);
        drop(permits);

        // The validator-only reserve remains untouched by a public flood.
        assert_eq!(
            node.validator_shard_permits.available_permits(),
            VALIDATOR_SHARD_CONCURRENCY
        );
    }

    #[tokio::test]
    async fn long_prompt_outside_reviewed_community_deadline_fails_before_enqueue() {
        let mut node = fake_node_with_workers(vec![(
            worker("idle-worker", &["inference"]),
            Instant::now(),
        )]);
        node.inference_model = Some(context_test_inference_model(512));

        // Four one-token words + internal BOS + 256 outputs fit the model's
        // context (261) but exceed the reviewed three-pass 3,900s
        // community budget. This must remain eligible for local/sharded
        // fallback and must never consume a queue slot.
        let error = dispatch_to_community_worker(
            &node,
            "ARC ARC ARC ARC".to_string(),
            INFERENCE_RUN_MAX_TOKENS,
            Some(test_model_id()),
        )
        .await
        .expect_err("impossible community deadline is rejected");
        assert!(error.local_fallback_safe);
        assert!(error.contains("exceeding the reviewed"), "{error}");
        assert!(node.community_work_results.as_ref().unwrap().is_empty());
        assert_eq!(node.attestation_nonce.load(Ordering::Relaxed), 0);
        assert!(
            node.community_work_queue
                .as_ref()
                .unwrap()
                .lock()
                .await
                .try_recv()
                .is_err()
        );
    }

    #[tokio::test]
    async fn recovery_probe_dispatch_is_restart_stable_and_rejects_duplicate_or_tampered_semantics()
    {
        let node = fake_node_with_workers(vec![(
            worker("w1", &["inference"]),
            std::time::Instant::now(),
        )]);
        let mut probe_bytes = [0u8; 32];
        probe_bytes[..arc_types::transaction::RECOVERY_REWARD_PROBE_PREFIX.len()]
            .copy_from_slice(&arc_types::transaction::RECOVERY_REWARD_PROBE_PREFIX);
        probe_bytes[arc_types::transaction::RECOVERY_REWARD_PROBE_PREFIX.len()..].fill(3);
        let probe_id = Hash256(probe_bytes);
        let queue = node.community_work_queue.as_ref().unwrap().clone();
        let task_node = node.clone();
        let first = tokio::spawn(async move {
            dispatch_to_community_worker_with_probe(
                &task_node,
                "ARC recovery probe".to_string(),
                1,
                Some(test_model_id()),
                Some(probe_id),
            )
            .await
        });
        let item = queue.lock().await.recv().await.expect("one recovery job");
        let (assignment_epoch, job_nonce) = recovery_probe_assignment(probe_id);
        assert_eq!(assignment_epoch, probe_id);
        let expected_job = arc_types::transaction::CommunityInferenceRewardBody::derive_job_id(
            &node.validator_address,
            &assignment_epoch,
            job_nonce,
            &parse_hash256_hex(&test_model_id(), "model").unwrap(),
            &arc_crypto::hash_bytes(b"ARC recovery probe"),
            1,
        );
        assert_eq!(item.job_id, expected_job.to_hex());
        assert_eq!(node.attestation_nonce.load(Ordering::Relaxed), 0);

        let duplicate = dispatch_to_community_worker_with_probe(
            &node,
            "ARC recovery probe".to_string(),
            1,
            Some(test_model_id()),
            Some(probe_id),
        )
        .await
        .expect_err("same probe must discover the existing job");
        assert!(duplicate.contains("already exists"));
        let tampered = dispatch_to_community_worker_with_probe(
            &node,
            "different semantics".to_string(),
            1,
            Some(test_model_id()),
            Some(probe_id),
        )
        .await
        .expect_err("one recovery identity cannot bind different input");
        assert!(tampered.contains("different inference semantics"));
        assert!(queue.lock().await.try_recv().is_err());
        first.abort();
        let _ = first.await;
    }

    #[tokio::test]
    async fn inference_run_recovery_retry_discovers_inflight_job_without_second_enqueue() {
        let node = fake_node_with_workers(vec![(
            worker("w1", &["inference"]),
            std::time::Instant::now(),
        )]);
        let mut probe_bytes = [0u8; 32];
        probe_bytes[..arc_types::transaction::RECOVERY_REWARD_PROBE_PREFIX.len()]
            .copy_from_slice(&arc_types::transaction::RECOVERY_REWARD_PROBE_PREFIX);
        probe_bytes[arc_types::transaction::RECOVERY_REWARD_PROBE_PREFIX.len()..].fill(4);
        let probe_id = Hash256(probe_bytes);
        let request = json!({
            "input": "ARC RPC recovery probe",
            "max_tokens": 1,
            "recovery_probe_id": format!("0x{}", probe_id.to_hex()),
        });
        let first_node = node.clone();
        let first_request = request.clone();
        let first = tokio::spawn(async move {
            inference_run(AxumState(first_node), Some(Json(first_request))).await
        });
        let queue = node.community_work_queue.as_ref().unwrap().clone();
        let item = queue.lock().await.recv().await.expect("one recovery job");

        let Json(replay) = inference_run(AxumState(node.clone()), Some(Json(request.clone())))
            .await
            .expect("retry returns discoverable in-flight status");
        assert_eq!(replay["success"], true);
        assert_eq!(replay["idempotent_replay"], true);
        assert_eq!(replay["recovery_probe_id"], request["recovery_probe_id"]);
        assert_eq!(replay["job_id"], format!("0x{}", item.job_id));
        assert_eq!(replay["settlement"]["status"], "assignment_in_progress");
        assert!(replay["settlement"]["worker"].is_null());
        assert!(replay["settlement"]["tx_hash"].is_null());
        assert_eq!(replay["settlement"]["submitted"], false);
        assert_eq!(replay["settlement"]["included"], false);
        assert_eq!(replay["settlement"]["confirmed"], false);
        assert!(replay["settlement"]["success"].is_null());
        assert!(replay["settlement"]["reward_base"].is_null());
        assert!(replay["settlement"]["reward_arc"].is_null());
        assert!(replay["settlement"]["receipt_url"].is_null());
        assert!(queue.lock().await.try_recv().is_err());

        let mut tampered = request;
        tampered["input"] = json!("different RPC semantics");
        let error = inference_run(AxumState(node), Some(Json(tampered)))
            .await
            .expect_err("same recovery id cannot bind another prompt");
        assert_eq!(error.0, StatusCode::CONFLICT);
        assert!(error.1.error.contains("different inference semantics"));
        first.abort();
        let _ = first.await;
    }

    #[tokio::test]
    async fn inference_run_surfaces_server_evidence_and_dispatches_at_shared_token_ceiling() {
        let node = fake_node_with_workers(vec![(
            worker("w1", &["inference"]),
            std::time::Instant::now(),
        )]);
        let queue = node.community_work_queue.as_ref().unwrap().clone();
        let results = node.community_work_results.as_ref().unwrap().clone();
        let observed_max = Arc::new(AtomicU32::new(0));
        let observed_max_worker = observed_max.clone();

        tokio::spawn(async move {
            let item = queue.lock().await.recv().await.expect("a job");
            observed_max_worker.store(item.max_tokens, Ordering::Relaxed);
            if let Some((_, pending)) = results.remove(&item.job_id) {
                let settlement_job_id = item.job_id.clone();
                let _ = pending.sender.send(CommunityDispatchOutcome {
                    result: WorkResult {
                        job_id: item.job_id,
                        worker_id: "w1".to_string(),
                        success: true,
                        declined: false,
                        output: "verified output".to_string(),
                        output_hash: format!("0x{}", Hash256::ZERO.to_hex()),
                        tokens_generated: 2,
                        total_ms: 10,
                        ms_per_token: 5,
                        engine: "integer test engine".to_string(),
                        error: None,
                        signed_attestation_hex: None,
                    },
                    verification: Some(CommunityVerificationSummary {
                        method: "authenticated_shard_quorum_2_of_3_per_range",
                        profile_bound: true,
                        quorum_verified: true,
                        execution_profile:
                            arc_inference::cached_integer_model::CANONICAL_REWARD_INFERENCE_PROFILE,
                        output_hash: format!("0x{}", Hash256::ZERO.to_hex()),
                        tokens_generated: 2,
                        ranges: 6,
                        range_position_quorums: 6,
                        signatures_required_per_quorum: 2,
                        replicas_contacted_per_quorum: 3,
                    }),
                    settlement: Some(json!({
                        "status": "pending_mined_receipt",
                        "tx_type": "0x25",
                        "tx_hash": format!("0x{}", Hash256([7; 32]).to_hex()),
                        "job_id": settlement_job_id,
                        "worker": "w1",
                        "submitted": true,
                        "included": false,
                        "confirmed": false,
                        "success": Value::Null,
                        "receipt_url": format!(
                            "/community/reward_receipt/0x{}",
                            Hash256([7; 32]).to_hex()
                        ),
                    })),
                });
            }
        });

        let Json(response) = match inference_run(
            AxumState(node),
            Some(Json(json!({
                // One exact tokenizer token keeps max-output dispatch inside
                // the reviewed 3-pass public deadline.
                "input": "x",
                "max_tokens": 4096,
                "bond": 999999,
                "challenge_period": 777,
            }))),
        )
        .await
        {
            Ok(response) => response,
            Err((status, Json(error))) => {
                panic!("inference_run failed with {status}: {}", error.error)
            }
        };

        assert_eq!(
            observed_max.load(Ordering::Relaxed),
            INFERENCE_RUN_MAX_TOKENS
        );
        assert_eq!(
            response["verification"]["method"],
            "authenticated_shard_quorum_2_of_3_per_range"
        );
        assert_eq!(response["verification"]["profile_bound"], true);
        assert_eq!(response["verification"]["quorum_verified"], true);
        assert_eq!(
            response["verification"]["execution_profile"],
            arc_inference::cached_integer_model::CANONICAL_REWARD_INFERENCE_PROFILE
        );
        assert_eq!(response["verification"]["range_position_quorums"], 6);
        assert_eq!(
            response["verification"]["signatures_required_per_quorum"],
            2
        );
        assert_eq!(
            response["inference"]["output_hash"], response["verification"]["output_hash"],
            "production-formatted worker and verification hashes must correlate exactly"
        );
        assert!(response["attestation"].get("bond").is_none());
        assert!(response["attestation"].get("challenge_period").is_none());
        assert_eq!(
            response["attestation"]["request_overrides_applied"], false,
            "community responses must not echo ignored local-attestation overrides"
        );
        assert_eq!(response["settlement"]["status"], "pending_mined_receipt");
        assert_eq!(response["settlement"]["tx_type"], "0x25");
        assert_eq!(response["settlement"]["worker"], "w1");
        assert_eq!(response["settlement"]["submitted"], true);
        assert_eq!(response["settlement"]["included"], false);
        assert_eq!(response["settlement"]["confirmed"], false);
        assert!(response["settlement"]["success"].is_null());
        assert_eq!(
            response["settlement"]["receipt_url"],
            format!("/community/reward_receipt/0x{}", Hash256([7; 32]).to_hex())
        );
    }

