    #[tokio::test]
    async fn faucet_submission_is_pending_until_canonical_execution() {
        let validator = KeyPair::generate_ed25519();
        let validator_address = validator.address();
        let recipient = KeyPair::generate_ed25519().address();
        let pool = arc_types::transaction::faucet_pool_address();
        let state = Arc::new(arc_state::StateDB::with_genesis(&[
            (pool, 2 * FAUCET_CLAIM_AMOUNT),
            (validator_address, 0),
        ]));
        state.seed_genesis_validators(&[(
            validator_address,
            arc_state::StateDB::MIN_VALIDATOR_STAKE,
        )]);
        let mempool = Arc::new(arc_mempool::Mempool::new(16));
        let node = build_node_state(
            state.clone(),
            mempool.clone(),
            validator_address,
            Some(Arc::new(validator)),
            arc_state::StateDB::MIN_VALIDATOR_STAKE,
            Instant::now(),
            Arc::new(AtomicU32::new(0)),
            None,
            None,
            None,
            None,
        );

        let Json(submitted) = faucet_claim(
            AxumState(node),
            Json(FaucetClaimRequest {
                address: recipient.to_hex(),
            }),
        )
        .await
        .unwrap();
        assert_eq!(submitted.status, "pending");
        assert_eq!(submitted.amount, FAUCET_CLAIM_AMOUNT);
        assert_eq!(mempool.len(), 1);
        assert_eq!(
            state.get_account(&pool).unwrap().balance,
            2 * FAUCET_CLAIM_AMOUNT
        );
        assert!(state.get_account(&recipient).is_none());
        let submitted_hash = Hash256::from_hex(&submitted.tx_hash).unwrap();
        assert!(state.get_receipt(&submitted_hash.0).is_none());

        let transaction = mempool.drain(1).pop().unwrap();
        let (_, receipts) = state
            .execute_block(&[transaction], validator_address)
            .unwrap();
        assert!(receipts[0].success);
        assert_eq!(
            state.get_account(&pool).unwrap().balance,
            FAUCET_CLAIM_AMOUNT
        );
        assert_eq!(
            state.get_account(&recipient).unwrap().balance,
            FAUCET_CLAIM_AMOUNT
        );
        assert!(state.get_receipt(&submitted_hash.0).is_some());
    }

    #[tokio::test]
    async fn faucet_route_rejects_pool_treasuries_reserves_and_existing_marker_without_supply_change()
     {
        let validator = KeyPair::generate_ed25519();
        let validator_address = validator.address();
        let pool = arc_types::transaction::faucet_pool_address();
        let state = Arc::new(arc_state::StateDB::with_genesis(&[
            (pool, 10 * FAUCET_CLAIM_AMOUNT),
            (validator_address, 0),
        ]));
        state.seed_genesis_validators(&[(
            validator_address,
            arc_state::StateDB::MIN_VALIDATOR_STAKE,
        )]);
        let ordinary = arc_crypto::hash_bytes(b"already-claimed-faucet-recipient");
        let existing_marker = arc_types::transaction::FaucetClaimBody::marker_address(&ordinary);
        let mut marker_account = state.get_or_create_account(&existing_marker);
        marker_account.nonce = 1;
        marker_account.code_hash = ordinary;
        state.update_account(&existing_marker, marker_account);

        let mempool = Arc::new(arc_mempool::Mempool::new(16));
        let node = build_node_state(
            state.clone(),
            mempool.clone(),
            validator_address,
            Some(Arc::new(validator)),
            arc_state::StateDB::MIN_VALIDATOR_STAKE,
            Instant::now(),
            Arc::new(AtomicU32::new(0)),
            None,
            None,
            None,
            None,
        );
        let before = state.state_summary();
        for target in [
            pool,
            arc_types::transaction::inference_reward_treasury_address(),
            arc_state::recovery::recovery_stake_reserve_address(),
            arc_state::v3_fee_treasury_address(),
            arc_crypto::hash_bytes(b"ARC-bridge-escrow"),
            existing_marker,
        ] {
            let (status, Json(error)) = faucet_claim(
                AxumState(node.clone()),
                Json(FaucetClaimRequest {
                    address: target.to_hex(),
                }),
            )
            .await
            .expect_err("reserved faucet recipient must fail before submission");
            assert_eq!(status, StatusCode::BAD_REQUEST, "target={target}");
            assert!(error.error.contains("reserved or marker"));
        }
        let after = state.state_summary();
        assert_eq!(mempool.len(), 0);
        assert!(node.faucet_claims.is_empty());
        assert_eq!(before.total_balance, after.total_balance);
        assert_eq!(before.account_count, after.account_count);
        assert_eq!(before.block_height, after.block_height);
        assert_eq!(before.state_root, after.state_root);
        assert_eq!(
            state.get_account(&pool).unwrap().balance,
            10 * FAUCET_CLAIM_AMOUNT
        );
    }

    fn tier1_request_transaction(key: &KeyPair) -> Transaction {
        let input_blob = b"paid request must stay dark".to_vec();
        let mut tx = Transaction {
            tx_type: TxType::InferenceRequest,
            from: key.address(),
            nonce: 0,
            body: TxBody::InferenceRequest(arc_types::transaction::InferenceRequestBody {
                request_id: arc_crypto::hash_bytes(b"rpc-tier1-request").0,
                model_id: arc_crypto::hash_bytes(b"exact-model-artifact"),
                input_hash: arc_crypto::hash_bytes(&input_blob),
                input_blob,
                max_tokens: 8,
                tier: 1,
                max_reward: 10,
                deadline_blocks: 20,
                committee_size: 5,
            }),
            fee: 0,
            gas_limit: 0,
            hash: Hash256::ZERO,
            signature: arc_crypto::Signature::null(),
            sig_verified: false,
        };
        tx.sign(key).unwrap();
        tx
    }

    #[test]
    fn paid_inference_gate_checks_envelope_body_and_preserves_refunds() {
        let key = KeyPair::generate_ed25519();
        let transfer = Transaction::new_transfer(key.address(), key.address(), 1, 0);
        for tx_type in [
            TxType::InferenceEscrowOpen,
            TxType::InferenceEscrowRelease,
            TxType::InferenceRequest,
            TxType::InferenceVote,
            TxType::InferenceFinalize,
        ] {
            let mut disguised = transfer.clone();
            disguised.tx_type = tx_type;
            assert!(
                uses_unready_paid_inference_protocol(&disguised),
                "restricted envelope {tx_type:?} must stay dark"
            );
        }

        let mut disguised_body = tier1_request_transaction(&key);
        disguised_body.tx_type = TxType::Transfer;
        assert!(uses_unready_paid_inference_protocol(&disguised_body));

        let refund = Transaction {
            tx_type: TxType::InferenceEscrowRefund,
            from: key.address(),
            nonce: 0,
            body: TxBody::InferenceEscrowRefund(
                arc_types::transaction::InferenceEscrowRefundBody {
                    request_id: [7; 32],
                    model_id: arc_crypto::hash_bytes(b"legacy-model"),
                    max_tokens: 8,
                    timeout_blocks: 20,
                },
            ),
            fee: 0,
            gas_limit: 0,
            hash: Hash256::ZERO,
            signature: arc_crypto::Signature::null(),
            sig_verified: false,
        };
        assert!(
            !uses_unready_paid_inference_protocol(&refund),
            "older locked funds must retain their signed refund path"
        );
    }

